"use client";

import Image from "next/image";
import { useEffect, useMemo, useState } from "react";

type View = "dashboard" | "ncrs" | "actions" | "reports" | "settings" | "detail";
type DetailTab = "Overview" | "Root cause" | "CAPA" | "Evidence" | "Management review" | "Activity";
type ActionItem = { id: string; ncrId: string; title: string; owner: string; dueDate: string; status: string; evidence: string; completedAt: string };
type Attachment = { id: string; fileName: string; contentType: string; size: number; category: string; createdAt: string };
type ActivityItem = { id: string; eventType: string; message: string; actor: string; createdAt: string };
type WhyStep = { id: string; position: number; answer: string };
type NcrRecord = {
  id: string; recordNumber: string; title: string; description: string; source: string; process: string; area: string;
  detectedAt: string; reportedBy: string; owner: string; status: string; priority: string; severity: number; occurrence: number;
  detectability: number; rpn: number; containment: string; affectedQty: number; disposition: string; dispositionNotes: string;
  approvalStatus: string; rootCause: string; rootCauseEvidence: string; effectivenessCriteria: string; effectivenessReviewDate: string;
  effectivenessResult: string; customerSupplier: string; copq: number; createdAt: string; updatedAt: string; closedAt: string | null;
  actions: ActionItem[]; attachments: Attachment[]; activity: ActivityItem[]; whySteps: WhyStep[];
};

type Draft = {
  title: string; description: string; source: string; process: string; area: string; detectedAt: string; reportedBy: string; owner: string;
  priority: string; severity: number; occurrence: number; detectability: number; containment: string; affectedQty: number; disposition: string;
  dispositionNotes: string; approvalStatus: string; rootCause: string; rootCauseEvidence: string; effectivenessCriteria: string;
  effectivenessReviewDate: string; customerSupplier: string; copq: number; whySteps: string[];
  actions: Array<{ title: string; owner: string; dueDate: string; status: string; evidence: string }>;
};

const today = "2026-08-14";
