    whySteps: [], actions: [{ id: "fa-5", ncrId: "fallback-39", title: "Add verification to setup checklist", owner: "Ethan Cole", dueDate: "2026-08-04", status: "Complete", evidence: "WI-MCH-014 Rev C", completedAt: "2026-08-04" }], attachments: [], activity: [],
